SELECT 

WHERE s.cinema_id = #{cinemaId}
AND o.order_no = #{orderNo}
AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT COALESCE(SUM(total_price), 0)
FROM ticket_order
WHERE status = 1
  AND pay_time >= #{startTime}
  AND pay_time < #{endTime}

SELECT m.id AS movieId, m.title AS movieTitle, m.poster AS moviePoster,
       COALESCE(SUM(o.total_price),0) AS boxOffice, COALESCE(SUM(o.seat_count),0) AS ticketCount
FROM movie m JOIN showtime s ON s.movie_id=m.id AND s.cinema_id=#{cinemaId}
LEFT JOIN ticket_order o ON o.showtime_id=s.id AND o.status=1
WHERE m.status=1 AND m.deleted=0
GROUP BY m.id,m.title,m.poster ORDER BY boxOffice DESC,m.id ASC LIMIT #{limit}
